"""Paso 2 de la materia: cada cursada que ya existia queda con una.

La 0002 agrego Course.subject como nullable para poder crear la columna sobre
una base con datos. Esta la completa: por cada carrera que tiene cursadas sin
materia crea "Sin asignar" y se las asigna. Recien despues la 0004 la vuelve
obligatoria.

Se crea solo en las carreras que la necesitan: una carrera sin cursadas no
tiene nada que completar, y una materia de relleno que nadie usa ensuciaria la
lista de materias.
"""
from django.db import migrations

SIN_ASIGNAR = "Sin asignar"


def assign_unassigned_subject(apps, schema_editor):
    Course = apps.get_model("academics", "Course")
    Subject = apps.get_model("academics", "Subject")

    # Un set y no distinct(): el ordering del Meta de Course se colaria en el
    # SELECT DISTINCT y devolveria la misma carrera una vez por cursada.
    career_ids = set(
        Course.objects.filter(subject__isnull=True).values_list("career_id", flat=True)
    )
    for career_id in career_ids:
        subject, _ = Subject.objects.get_or_create(career_id=career_id, name=SIN_ASIGNAR)
        Course.objects.filter(career_id=career_id, subject__isnull=True).update(
            subject=subject
        )


